#!/usr/bin/env python3
"""Creative spark generator for the creative-director. Usage: ideation.py "<song name>" [seed] [n]
Seeded (song name + seed) so a run is reproducible; change the seed for a new roll. It never decides for you:
it throws odd, concrete constraints and pairings at the concept so it doesn't default to the last song's look."""
import random, sys, hashlib
song = sys.argv[1] if len(sys.argv) > 1 else 'untitled'; seed = sys.argv[2] if len(sys.argv) > 2 else '0'; n = int(sys.argv[3]) if len(sys.argv) > 3 else 5
r = random.Random(int(hashlib.sha256((song + seed).encode()).hexdigest(), 16) % (2**32))
OBJECTS = ['ticket stub','price tag','luggage tag','receipt','polaroid caption','wristband','hotel key card','prescription label','flight board','scoreboard','boarding pass','parking ticket','library card','film leader countdown','VHS tracking bar','answering-machine display','fax header','security-camera timestamp','pawn-shop tag','bus-stop timetable','x-ray lightbox','pool-lane rope','mixtape cassette spine','bank statement line','shipping label']
WORLDS = ['a parking lot at 3 am','a pool in the last week of summer','a barber shop','a laundromat','a school gym after hours','a gas station','a hotel corridor','a bus window','a bedroom with the TV on','a rooftop','a car wash','a basement show','an airport gate','a record store','a phone screen','a kitchen at night','a loading dock','a shopping mall closing down']
CONSTRAINTS = ['no text for the first 20 seconds','one single shot held for a whole verse','every cut happens on a snare, none on the kick','only two colours plus black','one object appears in every section, bigger each time','the video is shot "through" something (glass, fence, window, fish-eye, rain)','captions only for the last word of each line','the chorus is the ONLY place with colour; verses are black and white','the chorus is silent visually (a frozen frame) while the music hits','type is always physical (written on a surface, never floating)','every transition is the same one trick, used 10 times, getting more extreme','the screen is a different device each section (phone, CRT, billboard, projector)','something is slowly removed from the frame over the whole song','the video ends on the first shot, changed','a counter runs the whole video and the last number matters','all motion is mirrored/duplicated and drifts out of sync as the song goes on']
TRANSITIONS = ['hard cut on the snare','match-cut on shape (circle to sun to coin)','fade through a flash of one brand colour','whip pan blur','stutter-freeze for 4 frames','frosted-glass wipe','paper tear reveal','light leak burn','slow dissolve over a full bar','dip to black on a held note','scale-punch on the kick','VHS tracking roll','slit-scan smear','camera flash pop']
REFS = ['a thrift-store catalogue','a 90s airline safety card','a cereal box','a driving-test manual','a CCTV monitor wall','a newspaper classified page','a church bulletin','an arcade high-score screen','a pharmacy leaflet','a school yearbook page','a travel-agent poster','a skate-video credits roll','a pawn-shop window','a boxing-weigh-in poster','a wedding-video lower third']
PALETTES = [('pool teal','sunset orange'),('black','opium red'),('lime','navy'),('bone white','bruise purple'),('chrome silver','tomato red'),('mustard','dark teal'),('hot pink','forest green'),('ice blue','warm amber'),('olive','cream'),('petrol blue','neon yellow')]
STRUCTS = ['a countdown to something that never arrives','the same 8 bars shown from 4 different "cameras"','the video is a tour of ONE room','the video is a list (a to-do, a menu, a receipt) that gets filled in','the video is the artist leaving a place, one object at a time','day turns to night across the song','a slow zoom that never stops, 90 s long','the picture is a contact sheet that picks one frame at each drop','the lyrics are written by hand, crossed out and rewritten','a game HUD: health, ammo, score tied to the lyrics']
def pick(xs, k=1): return r.sample(xs, k)
print(f'# Spark sheet for "{song}" (seed {seed}). Use at least 2 of these, ignore the rest, and say which and why.\n')
for i in range(n):
    p = pick(PALETTES)[0]
    print(f'## Roll {i+1}')
    print('- World:', pick(WORLDS)[0]); print('- Native object (the counter/tag/stamp could be a):', ', '.join(pick(OBJECTS, 2)))
    print('- Reference from OUTSIDE music videos:', pick(REFS)[0]); print('- Constraint:', pick(CONSTRAINTS)[0]); print('- Structure:', pick(STRUCTS)[0])
    print('- Transition vocabulary:', ', '.join(pick(TRANSITIONS, 2))); print(f'- Palette: {p[0]} + {p[1]} (+ black)\n')
